const theme = $('Get Active Theme').first().json || {};
const THEME_ID = Number(theme.id || 0);
const THEME_TITLE = String(theme.title || 'theme').trim();

const THEME_KEYWORDS = Array.isArray(theme.keywords)
  ? theme.keywords
  : String(theme.keywords || '')
      .replace(/[{}"]/g, '')
      .split(',')
      .map(s => s.trim())
      .filter(Boolean);

const NEGATIVE_KEYWORDS = Array.isArray(theme.negative_keywords)
  ? theme.negative_keywords
  : String(theme.negative_keywords || '')
      .replace(/[{}"]/g, '')
      .split(',')
      .map(s => s.trim())
      .filter(Boolean);

const sourceData = $('Set Initial Variables').first().json;
const sourceId = sourceData.source_id;
const sourceUrl = sourceData.source_url;

const inputData = $input.first().json;
const inputPosts = inputData.posts || [];
const subscribersText = inputData.subscribers_text || '';

// --- НАСТРОЙКИ ---
const DAYS_TO_KEEP = 14;
const STOP_WORDS = ['erid:', 'реклама', 'подписывайтесь', 'жми сюда', 'промокод', 'скидка', 'партнерский'];
const MAX_LINKS = 3;
const MAX_POSTS_PER_SOURCE = 20;

function normalize(text) {
  return String(text || '')
    .toLowerCase()
    .replace(/ё/g, 'е')
    .replace(/\s+/g, ' ')
    .trim();
}

function makeCategory(themeTitle) {
  const t = normalize(themeTitle);
  if (t.includes('налог')) return 'tax';
  return t
    .replace(/[^a-zа-я0-9]+/gi, '_')
    .replace(/^_+|_+$/g, '')
    .slice(0, 50) || 'theme';
}

const THEME_CATEGORY = makeCategory(THEME_TITLE);

function getMatchedKeywords(text) {
  const normalized = normalize(text);

  const matched = THEME_KEYWORDS.filter(keyword => {
    const k = normalize(keyword);
    return k && normalized.includes(k);
  });

  const negative = NEGATIVE_KEYWORDS.filter(keyword => {
    const k = normalize(keyword);
    return k && normalized.includes(k);
  });

  return { matched, negative };
}

const cutoffDate = new Date();
cutoffDate.setDate(cutoffDate.getDate() - DAYS_TO_KEEP);

// 1. ПАРСИМ ПОДПИСЧИКОВ
let subscribersCount = null;
if (subscribersText) {
  const match = subscribersText.match(/([0-9.,KM]+)\s+subscribers?/i);
  if (match) {
    const subsStr = match[1].trim();
    if (subsStr.includes('K')) subscribersCount = Math.round(parseFloat(subsStr.replace('K', '').replace(',', '.')) * 1000);
    else if (subsStr.includes('M')) subscribersCount = Math.round(parseFloat(subsStr.replace('M', '').replace(',', '.')) * 1000000);
    else subscribersCount = parseInt(subsStr.replace(/[^0-9]/g, '')) || null;
  }
}

const posts = [];

for (const html of inputPosts) {
  if (posts.length >= MAX_POSTS_PER_SOURCE) break;

  // --- ID ПОСТА ---
  let postId = null;
  const footerMatch = html.match(/t\.me\/[^\/]+\/(\d+)/);
  if (footerMatch) postId = footerMatch[1];
  if (!postId) continue;

  // 🔗 ССЫЛКА
  let cleanSourceUrl = String(sourceUrl || '').replace('/s/', '/');
  if (cleanSourceUrl.endsWith('/')) cleanSourceUrl = cleanSourceUrl.slice(0, -1);
  const externalUrl = `${cleanSourceUrl}/${postId}`;

  // --- ДАТА ---
  const dateMatch = html.match(/<time datetime="([^"]+)"/);
  let publishedAt = null;
  if (dateMatch) {
    publishedAt = dateMatch[1];
    if (new Date(publishedAt) < cutoffDate) continue;
  } else {
    continue;
  }

  // --- ТЕКСТ ---
  const textMatch = html.match(/<div class="tgme_widget_message_text[^>]*>([\s\S]*?)<\/div>/);
  let rawHtml = textMatch ? textMatch[1] : '';

  let text = rawHtml
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<b>(.*?)<\/b>/gi, '**$1**')
    .replace(/<strong>(.*?)<\/strong>/gi, '**$1**')
    .replace(/<i>(.*?)<\/i>/gi, '_$1_')
    .replace(/<em>(.*?)<\/em>/gi, '_$1_')
    .replace(/<a href="([^"]+)".*?>(.*?)<\/a>/gi, '[$2]($1)')
    .replace(/&quot;/g, '"')
    .replace(/&amp;/g, '&')
    .replace(/&nbsp;/g, ' ')
    .replace(/<[^>]+>/g, '')
    .trim();

  // БАЗОВЫЕ ФИЛЬТРЫ
  if (text.length < 50) continue;
  if (text.includes('Forwarded from')) continue;

  const lowerText = text.toLowerCase();
  if (STOP_WORDS.some(word => lowerText.includes(word))) continue;

  const linkCount = (text.match(/http/g) || []).length;
  const mdLinkCount = (text.match(/\[.*?\]\(.*?\)/g) || []).length;
  if (linkCount > MAX_LINKS || mdLinkCount > MAX_LINKS) continue;

  // ФИЛЬТР АКТИВНОЙ ТЕМЫ
  const { matched, negative } = getMatchedKeywords(`${text} ${externalUrl}`);
  if (matched.length === 0) continue;
  if (negative.length > 0) continue;

  let title = text.length <= 100 ? text : text.substring(0, 100) + '...';

  // --- МЕТРИКИ ---
  let views = 0;
  const viewsMatch = html.match(/class=["']tgme_widget_message_views["'][^>]*>([^<]+)<\/span>/);
  if (viewsMatch) {
    const rawViews = viewsMatch[1].trim();
    if (rawViews.includes('K')) views = Math.round(parseFloat(rawViews.replace('K', '').replace(',', '.')) * 1000);
    else if (rawViews.includes('M')) views = Math.round(parseFloat(rawViews.replace('M', '').replace(',', '.')) * 1000000);
    else views = parseInt(rawViews.replace(/[^\d]/g, '')) || 0;
  }

  let totalReactions = 0;
  const countMatches = html.matchAll(/class=["']tgme_widget_message_reaction_count["'][^>]*>([^<]+)<\/span>/g);
  for (const match of countMatches) {
    const s = match[1].trim();
    let count = 0;
    if (s.includes('K')) count = Math.round(parseFloat(s.replace('K','').replace(',','.')) * 1000);
    else if (s.includes('M')) count = Math.round(parseFloat(s.replace('M','').replace(',','.')) * 1000000);
    else count = parseInt(s.replace(/[^\d]/g, '')) || 0;
    totalReactions += count;
  }

  let reachRate = 0;
  if (subscribersCount && subscribersCount > 0 && views > 0) {
    reachRate = (views / subscribersCount) * 100;
    reachRate = Math.round(reachRate * 100) / 100;
  }

  let er = 0;
  if (views > 0 && totalReactions > 0) {
    er = (totalReactions / views) * 100;
    er = Math.round(er * 100) / 100;
  }

  const images = [];
  const imageMatches = html.matchAll(/background-image:\s*url\(['"]([^'"]+)['"]/g);
  for (const match of imageMatches) {
    if (match[1].includes('telesco.pe')) images.push(match[1]);
  }

  posts.push({
    post_id: postId,
    external_url: externalUrl,
    text,
    title,
    published_at: publishedAt,
    views,
    images,
    total_reactions: totalReactions,
    er,
    reach_rate: reachRate,
    category: THEME_CATEGORY,
    platform: 'telegram',
    matched_theme_id: THEME_ID,
    matched_keywords: matched,
    relevance_score: matched.length,
    is_theme_relevant: true
  });
}

// ЗАЩИТА ОТ ДУБЛЕЙ
const uniquePosts = [];
const seenIds = new Set();
for (const post of posts) {
  if (!seenIds.has(post.post_id)) {
    seenIds.add(post.post_id);
    uniquePosts.push(post);
  }
}

return [{
  json: {
    source_id: Number(sourceId),
    theme_id: THEME_ID,
    theme_title: THEME_TITLE,
    subscribers_count: Number(subscribersCount || 0),
    posts: Array.isArray(uniquePosts) ? uniquePosts : [],
    has_posts: Array.isArray(uniquePosts) && uniquePosts.length > 0,
    reason: uniquePosts.length ? 'telegram_parsed_by_active_theme' : 'telegram_empty_after_theme_filter'
  }
}];

// Собираем все настройки в удобный объект
const settings = {};

const items = $input.all();

items.forEach(item => {
  const key = item.json.setting_key;
  const value = item.json.setting_value;
  settings[key] = value;
});

// Возвращаем один объект со всеми настройками
return [{
  json: {
    admin_chat_id: settings.admin_chat_id,
    days_before_ideas: settings.days_before_ideas,
    supabase_url: settings.supabase_url,
    default_channel_name: settings.default_channel_name
  }
}];

const clean = (v, fallback = '') => {
  if (v === null || v === undefined) return fallback;
  return String(v)
    .replace(/\u0000/g, '')
    .replace(/[\u0001-\u001f]/g, ' ')
    .trim();
};

const body = {
  source_id: Number($json.source_id),
  platform: clean($json.platform, 'website'),
  title: clean($json.title, 'Без названия'),
  content: clean($json.text || $json.content, 'Без текста'),
  external_id: Number($json.post_id),
  external_url: clean($json.external_url),
  views_count: Number($json.views || 0),
  likes_count: Number($json.total_reactions || 0),
  published_at: $json.published_at || null,
  parsed_at: new Date().toISOString(),
  metrics_updated_at: new Date().toISOString(),
  er: Number($json.er || 0),
  reach_rate: Number($json.reach_rate || 0),
  category: clean($json.category, 'theme'),
  matched_theme_id: $json.matched_theme_id ? Number($json.matched_theme_id) : null,
  matched_keywords: Array.isArray($json.matched_keywords) ? $json.matched_keywords : [],
  relevance_score: Number($json.relevance_score || 0),
  is_theme_relevant: $json.is_theme_relevant !== false
};

return [{
  json: {
    ...$json,
    insert_body: JSON.stringify(body)
  }
}];

const posts = Array.isArray($json.posts) ? $json.posts : [];

if (posts.length === 0) {
  return [];
}

return posts.map(post => ({
  json: {
    source_id: Number($json.source_id),
    platform: post.platform || 'website',
    post_id: Number(post.post_id),
    external_url: post.external_url,
    text: post.text || post.content || '',
    title: post.title || 'Без названия',
    published_at: post.published_at || null,
    views: Number(post.views || 0),
    images: Array.isArray(post.images) ? post.images : [],
    total_reactions: Number(post.total_reactions || 0),
    er: Number(post.er || 0),
    reach_rate: Number(post.reach_rate || 0),
    category: post.category || 'theme',
    matched_theme_id: post.matched_theme_id || $json.theme_id || null,
    matched_keywords: Array.isArray(post.matched_keywords) ? post.matched_keywords : [],
    relevance_score: Number(post.relevance_score || 0),
    is_theme_relevant: post.is_theme_relevant !== false
  }
}));

const theme = $('Get Active Theme').first().json || {};
const THEME_ID = Number(theme.id || 0);
const THEME_TITLE = String(theme.title || 'theme').trim();

const THEME_KEYWORDS = Array.isArray(theme.keywords)
  ? theme.keywords
  : String(theme.keywords || '')
      .replace(/[{}"]/g, '')
      .split(',')
      .map(s => s.trim())
      .filter(Boolean);

const NEGATIVE_KEYWORDS = Array.isArray(theme.negative_keywords)
  ? theme.negative_keywords
  : String(theme.negative_keywords || '')
      .replace(/[{}"]/g, '')
      .split(',')
      .map(s => s.trim())
      .filter(Boolean);

const sourceData = $('Set Initial Variables').first().json;

const sourceId = Number(sourceData.source_id);
const sourceUrl = String(sourceData.source_url || '').trim();
const fetchUrl = String(sourceData.fetch_url || sourceData.rss_url || sourceUrl).trim();
const sourceName = String(sourceData.source_name || '').trim();

const input = $input.first().json || {};
let raw = input.data ?? input.body ?? input.response ?? input.html ?? '';

if (typeof raw !== 'string') {
  raw = JSON.stringify(raw);
}

// Сколько материалов берем с одного RSS/сайта.
// Если источников 5-10, суммарно получится до 20+ новостей по теме.
const MAX_POSTS_PER_SOURCE = 20;

function normalize(text) {
  return String(text || '')
    .toLowerCase()
    .replace(/ё/g, 'е')
    .replace(/\s+/g, ' ')
    .trim();
}

function makeCategory(themeTitle) {
  const t = normalize(themeTitle);
  if (t.includes('налог')) return 'tax';
  return t
    .replace(/[^a-zа-я0-9]+/gi, '_')
    .replace(/^_+|_+$/g, '')
    .slice(0, 50) || 'theme';
}

const THEME_CATEGORY = makeCategory(THEME_TITLE);

function decodeHtml(text) {
  return String(text || '')
    .replace(/<!\[CDATA\[/g, '')
    .replace(/\]\]>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#034;/g, '"')
    .replace(/&#039;/g, "'")
    .replace(/&apos;/g, "'")
    .replace(/&laquo;/g, '«')
    .replace(/&raquo;/g, '»')
    .replace(/&mdash;/g, '—')
    .replace(/&ndash;/g, '–')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>');
}

function stripTags(text) {
  return decodeHtml(String(text || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
  )
    .replace(/\s+/g, ' ')
    .trim();
}

function getTag(block, tag) {
  const re = new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'i');
  const match = block.match(re);
  return match ? stripTags(match[1]) : '';
}

function getLink(block) {
  let link = getTag(block, 'link');

  if (!link) {
    const atom = block.match(/<link[^>]+href=["']([^"']+)["']/i);
    if (atom) link = atom[1];
  }

  if (!link) {
    const guid = block.match(/<guid[^>]*>([\s\S]*?)<\/guid>/i);
    if (guid && guid[1].includes('http')) link = stripTags(guid[1]);
  }

  return String(link || '').trim();
}

function hashToInt(str) {
  let hash = 0;
  const s = String(str || '');
  for (let i = 0; i < s.length; i++) {
    hash = ((hash << 5) - hash) + s.charCodeAt(i);
    hash |= 0;
  }
  return Math.abs(hash);
}

function getMatchedKeywords(title, description, url) {
  const text = normalize(`${title} ${description} ${url}`);

  const matched = THEME_KEYWORDS.filter(keyword => {
    const k = normalize(keyword);
    return k && text.includes(k);
  });

  const negative = NEGATIVE_KEYWORDS.filter(keyword => {
    const k = normalize(keyword);
    return k && text.includes(k);
  });

  return { matched, negative };
}

function makePost({ title, description, url, date }) {
  title = stripTags(title);
  description = stripTags(description);
  url = String(url || '').trim();

  if (!title || title.length < 8) return null;
  if (!url || !url.startsWith('http')) return null;

  const { matched, negative } = getMatchedKeywords(title, description, url);

  // Главный фильтр тематичности: материал проходит только если нашлось хотя бы 1 ключевое слово активной темы.
  if (matched.length === 0) return null;

  // Минус-слова темы: реклама, скидки, праздники и т.д.
  if (negative.length > 0) return null;

  let publishedAt = new Date().toISOString();
  if (date) {
    const d = new Date(date);
    if (!isNaN(d.getTime())) publishedAt = d.toISOString();
  }

  const text = description ? `${title}\n\n${description}` : title;

  return {
    post_id: hashToInt(url),
    external_url: url,
    text,
    title: title.slice(0, 180),
    published_at: publishedAt,
    views: 0,
    images: [],
    total_reactions: 0,
    er: 0,
    reach_rate: 0,
    category: THEME_CATEGORY,
    platform: 'website',
    matched_theme_id: THEME_ID,
    matched_keywords: matched,
    relevance_score: matched.length,
    is_theme_relevant: true
  };
}

function parseRss(xml) {
  const posts = [];

  const itemRe = /<item[\s\S]*?<\/item>/gi;
  const items = xml.match(itemRe) || [];

  for (const item of items) {
    if (posts.length >= MAX_POSTS_PER_SOURCE) break;

    const title = getTag(item, 'title');
    const description = getTag(item, 'description') || getTag(item, 'content:encoded');
    const url = getLink(item);
    const date = getTag(item, 'pubDate') || getTag(item, 'dc:date');

    const post = makePost({ title, description, url, date });
    if (post) posts.push(post);
  }

  const entryRe = /<entry[\s\S]*?<\/entry>/gi;
  const entries = xml.match(entryRe) || [];

  for (const entry of entries) {
    if (posts.length >= MAX_POSTS_PER_SOURCE) break;

    const title = getTag(entry, 'title');
    const description = getTag(entry, 'summary') || getTag(entry, 'content');
    const url = getLink(entry);
    const date = getTag(entry, 'updated') || getTag(entry, 'published');

    const post = makePost({ title, description, url, date });
    if (post) posts.push(post);
  }

  return posts;
}

function parseGenericHtml(html) {
  const posts = [];
  const linkRe = /<a[^>]+href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi;

  let m;
  while ((m = linkRe.exec(html)) !== null && posts.length < MAX_POSTS_PER_SOURCE) {
    let url = m[1];
    const title = stripTags(m[2]);

    if (!url.startsWith('http')) {
      try {
        url = new URL(url, fetchUrl).toString();
      } catch (e) {
        continue;
      }
    }

    const post = makePost({
      title,
      description: '',
      url,
      date: new Date().toISOString()
    });

    if (post) posts.push(post);
  }

  return posts;
}

const looksLikeRss =
  raw.includes('<rss') ||
  raw.includes('<feed') ||
  raw.includes('<item') ||
  raw.includes('<entry');

const posts = looksLikeRss ? parseRss(raw) : parseGenericHtml(raw);

// Убираем дубли внутри одного источника
const uniquePosts = [];
const seen = new Set();
for (const post of posts) {
  const key = post.external_url || post.post_id;
  if (seen.has(key)) continue;
  seen.add(key);
  uniquePosts.push(post);
}

return [{
  json: {
    source_id: sourceId,
    source_name: sourceName,
    source_url: sourceUrl,
    fetch_url: fetchUrl,
    theme_id: THEME_ID,
    theme_title: THEME_TITLE,
    theme_keywords: THEME_KEYWORDS,
    subscribers_count: 0,
    posts: uniquePosts,
    has_posts: uniquePosts.length > 0,
    reason: uniquePosts.length
      ? (looksLikeRss ? 'rss_parsed_by_active_theme' : 'html_parsed_by_active_theme')
      : (looksLikeRss ? 'rss_empty_after_theme_filter' : 'html_empty_after_theme_filter')
  }
}];
